SELECT row_to_json(a)::text FROM account_deletion_audit a
WHERE status='SUCCEEDED' AND expires_at > #{now} AND id > #{after}
ORDER BY id LIMIT 100

SELECT id FROM app_user WHERE role='USER'
  AND encode(sha256(convert_to('my-bill/account-deletion/v1/' || id::text,'UTF8')),'hex')=#{digest}
ORDER BY id LIMIT 2
